"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["8577"],{27414(e){e.exports=JSON.parse('{"id":"FIN-1240","slug":"supply-side-economics","term":"Supply-Side Economics","also_known_as":[],"difficulty":"Advanced","definition":"Supply-side economics is a school of economic thought which holds that economic growth is best promoted by policies that increase the economy\'s capacity to produce, such as lower taxes, reduced regulation and incentives to work, save and invest.","explanation":["While Keynesian economics focuses on demand, supply-side economics focuses on production. It argues that high tax rates and heavy regulation discourage work, investment and innovation, limiting growth.","Supply-side policies typically include cutting marginal income and corporate tax rates, reducing regulation, encouraging competition and making labour markets more flexible.","The approach became prominent in the United States in the 1980s under President Ronald Reagan, and similar ideas influenced policy in the United Kingdom under Margaret Thatcher. A well-known supply-side idea is the Laffer curve, associated with economist Arthur Laffer, which suggests that cutting very high tax rates could increase tax revenue by encouraging more economic activity.","For example, supply-side economists might argue that lowering the corporate tax rate would encourage businesses to invest more, raising productivity and wages over time.","Critics argue that tax cuts often benefit higher earners most and usually reduce revenue, increasing budget deficits. Most economists agree supply-side factors matter for long-term growth, but disagree about the size of the effects."],"note":"","total":1500,"prev":{"slug":"supply-curve","term":"Supply Curve"},"next":{"slug":"survivorship-bias","term":"Survivorship Bias"}}')}}]);